fn covering(meetings: List[List[Int]], t: Int) -> Int {
  return meetings.count(fn(m) => (m.get_or(0, 0) <= t) and (t < m.get_or(1, 0)))
}

pub fn rooms(meetings: List[List[Int]]) -> Int {
  let starts = meetings.map(fn(m) => m.get_or(0, 0))
  let loads = starts.map(fn(t) => covering(meetings, t))
  return loads.fold(0, fn(best, c) => best.max(c))
}
